head.b:template-skin:
body#layout{background:#eef3f5;font-family:system-ui,'Segoe UI',Tahoma,sans-serif;direction:rtl;min-width:0;padding:0 0 30px;color:#0f2a33}
body#layout:before{content:'TCNOPS 2026  \2014  لوحة تنسيق القالب';display:block;margin:0 0 6px;padding:20px 22px;border-radius:16px;background:linear-gradient(135deg,#0f2a33,#0f7f86);color:#fff;font:700 20px system-ui,sans-serif;box-shadow:0 14px 30px -18px #0f2a33}
body#layout:after{content:'الأصفر = لوحة المزايا (نعم/لا)  \00b7  الأخضر المنقّط = مساحات إعلانية: الصق الكود فيظهر في مكانه، والفارغ لا يظهر  \00b7  الأبيض = محتوى الموقع';display:block;margin:12px 0 0;padding:10px 14px;border-radius:10px;background:#fff;color:#4a6470;font:500 12.5px/1.8 system-ui,sans-serif;border:1px solid #d7e3e8}
body#layout .hdr,body#layout .ftr{position:static;backdrop-filter:none;background:transparent;border:0}
body#layout .zone,body#layout .tcn-panel,body#layout .anchor-ad{display:block!important;position:static!important;min-height:0;box-shadow:none;border:0;background:transparent;padding:0}
body#layout .section{margin:0 0 12px!important;padding:8px!important;border-radius:14px;background:#fff!important;border:1px solid #d7e3e8!important;box-shadow:0 6px 16px -14px #0f2a33}
body#layout .section h4{margin:2px 4px 8px;font:700 13.5px system-ui,sans-serif;color:#0f2a33}
body#layout .widget{border-radius:10px!important}
body#layout .tcn-panel .section{background:#fff8e1!important;border:1px solid #f2cf66!important}
body#layout .tcn-panel .section h4{color:#8a6100}
body#layout .zone .section{background:#f2fbfa!important;border:1px dashed #6cc1bc!important;box-shadow:none}
body#layout .zone .section h4{color:#0f7f86;font-weight:600}
body#layout .hdr-in,body#layout .fcols,body#layout .layout{display:block}
body#layout .layout{overflow:hidden;padding-top:6px}
body#layout .main{float:right;width:63%}
body#layout .side{float:left;width:35%}
body#layout .fcols{overflow:hidden}
body#layout .fcols>div{float:right;width:32%;margin-inline-end:1.3%}
body#layout .brand-sec,body#layout .nav{width:auto}
body#layout .fbar,body#layout .hdr-tools,body#layout .menu-btn,body#layout .bnav,body#layout .to-top,body#layout .progress,body#layout dialog,body#layout .ticker,body#layout .anchor-ad .x{display:none}

body.script:
//
(function () {
  /* يقرأ لوحة المزايا قبل رسم الصفحة: لا وميض عند إخفاء أي كتلة */
  var d = document, S = {}, el = d.getElementById("tcn-settings");
  if (el) {
    var txt = el.innerHTML.replace(/<br\s*\/?>/gi, "\n").replace(/<\/(p|div)>/gi, "\n").replace(/<[^>]+>/g, "");
    var ta = d.createElement("textarea"); ta.innerHTML = txt; txt = ta.value;
    txt.split(/\n/).forEach(function (line) {
      if (/^\s*(#|═|—|-{2,})/.test(line)) return;
      var m = line.match(/^\s*([^:=#]+?)\s*[:=]\s*(.*?)\s*$/);
      if (m) S[m[1].trim().replace(/\s+/g, "_")] = m[2];
    });
  }
  var P = null;
  try { P = JSON.parse(localStorage.getItem("tcn-preview") || "null"); } catch (e) { }
  if (P) for (var k in P) S[k] = P[k];
  window.TCN_S = S; window.TCN_SAVED_KEYS = P ? Object.keys(P) : [];
  var SEL = window.TCN_SEL || {}, css = "";
  for (var key in SEL) if (S[key] !== undefined && /^(لا|no|off|false|0)$/i.test(S[key])) css += SEL[key] + "{display:none!important}";
  if (S["إظهار_الشريط_الجانبي"] && /^(لا|no|off)$/i.test(S["إظهار_الشريط_الجانبي"])) css += ".layout{grid-template-columns:minmax(0,1fr)!important}";
  var st = d.createElement("style"); st.id = "tcn-off"; st.textContent = css; d.head.appendChild(st);
})();

